INSERT INTO _migration_504_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_alphabet_s2_001', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'How many vowels does the Akan (Twi) alphabet have?', 'multiple_choice', NULL, '["A. 7","B. 5","C. 6","D. 10"]', 'A', 'The Twi alphabet has seven vowels: a, e, ɛ, i, o, ɔ and u. English has five basic vowel letters, which is why 5 is a tempting but wrong answer for Twi. Therefore the correct answer is A: 7.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_002', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which letter does NOT appear in the Twi alphabet?', 'multiple_choice', NULL, '["A. ɛ","B. c","C. ɔ","D. y"]', 'B', 'The Twi alphabet does not contain the letters c, j, q, v, x or z. The special vowels ɛ and ɔ and the consonant y are all genuine Twi letters, so c is the only option that is excluded. Therefore the correct answer is B: c.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_003', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which of the following is a vowel in the Twi alphabet?', 'multiple_choice', NULL, '["A. b","B. t","C. ɔ","D. s"]', 'C', 'Ɔ (open o) is one of the seven Twi vowels — a, e, ɛ, i, o, ɔ, u. The letters b, t and s are consonants, so they cannot be vowel sounds. Therefore the correct answer is C: ɔ.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_004', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In Twi spelling, “hw” in the word “hwɛ” (look) is an example of what?', 'multiple_choice', NULL, '["A. A diphthong — two vowels gliding together","B. A tone mark placed above a syllable","C. A pair of silent letters","D. A digraph — two letters written together to represent a single sound"]', 'D', 'Twi uses digraphs such as dw, gw, hw, kw, ky, nw, ny and tw, where two letters together spell one consonant sound. Since h and w are consonants, “hw” cannot be a diphthong, and both letters are pronounced. Therefore the correct answer is D: A digraph — two letters written together to represent a single sound.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_005', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Twi is described as a tonal language. What does this mean?', 'multiple_choice', NULL, '["A. The pitch at which a syllable is spoken can change the meaning of a word","B. Every sentence must be sung to a fixed melody","C. Words are stressed only by making them louder","D. Words are written with musical notes"]', 'A', 'In a tonal language, high and low pitch distinguish words that otherwise have the same letters — for example “papa” can mean “good” or “fan” depending on the tones. Tone is about pitch, not loudness or singing, and it is normally not written in everyday Twi spelling. Therefore the correct answer is A: The pitch at which a syllable is spoken can change the meaning of a word.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_006', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which two special vowels does the Twi alphabet add to the basic Latin vowels?', 'multiple_choice', NULL, '["A. ɑ and ə","B. ɛ and ɔ","C. ë and ö","D. æ and œ"]', 'B', 'Twi writing adds ɛ (open e) and ɔ (open o) to the five Latin vowels, giving the seven-vowel set a, e, ɛ, i, o, ɔ, u. The pairs ɑ/ə, ë/ö and æ/œ do not belong to the standard Twi alphabet. Therefore the correct answer is B: ɛ and ɔ.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_007', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'How many letters are there in the full Akan (Twi) alphabet?', 'multiple_choice', NULL, '["A. 21","B. 24","C. 22","D. 26"]', 'C', 'The Twi alphabet has 22 letters: 15 consonants (b, d, f, g, h, k, l, m, n, p, r, s, t, w, y) and 7 vowels (a, e, ɛ, i, o, ɔ, u). The English alphabet has 26 letters, which makes 26 a common wrong guess. Therefore the correct answer is C: 22.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_alphabet_s2_008', 'topic_bece_ghlang_alphabet', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which of these words begins with a Twi digraph?', 'multiple_choice', NULL, '["A. Hene (chief)","B. Wura (owner)","C. Ase (under)","D. Hwɛ (look)"]', 'D', 'Hwɛ begins with the digraph “hw”, two letters spelling one consonant sound. Hene begins with the single letter h, wura with w, and ase with the vowel a, so none of them starts with a digraph. Therefore the correct answer is D: Hwɛ (look).', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_504_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_504_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_504_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_504_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_504_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_504_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_504_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_504_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_504_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_504_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
